def urgency(days_left):
    if days_left == 0:
        return "🔴", "today"
    if days_left == 1:
        return "🔴", "tomorrow"
    if days_left <= 3:
        return "🔴", f"in {days_left} days"
    return "🟠", f"in {days_left} days"


# one message per person: group the deadlines by chat
lines_per_chat = {}
ids_per_chat = {}

for item in _items:
    deadline = item["json"]
    chat = deadline["chat_id"]

    if chat not in lines_per_chat:
        lines_per_chat[chat] = []
        ids_per_chat[chat] = []

    icon, when = urgency(deadline["days_left"])
    lines_per_chat[chat].append(f"{icon} {deadline['title']} ({deadline['course']})")
    lines_per_chat[chat].append(f"      {deadline['due_pretty']} · {when}")
    ids_per_chat[chat].append(str(deadline["id"]))

results = []
for chat in lines_per_chat:
    count = len(ids_per_chat[chat])
    plural = "s" if count > 1 else ""
    header = f"☀️ Good morning! {count} deadline{plural} coming up:\n\n"

    results.append({
        "json": {
            "chatId": chat,
            "text": header + "\n".join(lines_per_chat[chat]),
            "ids": ",".join(ids_per_chat[chat]),
        }
    })

return results
